div.script:
document.addEventListener("DOMContentLoaded", function () {

    function reloj() {

        const n =
            document.getElementById("kds-clock");

        if (!n) return;

        n.textContent =
            new Date().toLocaleTimeString(
                "es-CR",
                {
                    hour: "2-digit",
                    minute: "2-digit"
                }
            );
    }

    reloj();

    setInterval(reloj, 1000);


    document.addEventListener(
        "click",
        async function (event) {

            const button =
                event.target.closest(".kds-action");

            if (!button) return;

            button.disabled = true;

            try {

                const response =
                    await fetch(
                        "/ibloom/kitchen/state",
                        {
                            method: "POST",
                            headers: {
                                "Content-Type":
                                    "application/json"
                            },
                            body:
                                JSON.stringify({
                                    order_id:
                                        Number(
                                            button.dataset.order
                                        ),
                                    state:
                                        button.dataset.state
                                })
                        }
                    );

                const data =
                    await response.json();

                if (!response.ok || !data.ok) {
                    throw new Error(
                        data.error || "Error"
                    );
                }

                window.location.reload();

            } catch (error) {

                alert(
                    "No se pudo actualizar el pedido."
                );

                button.disabled = false;
            }

        }
    );


    const refresh =
        document.getElementById("kds-refresh");

    if (refresh) {
        refresh.onclick = function () {
            window.location.reload();
        };
    }


    const fullscreen =
        document.getElementById("kds-fullscreen");

    if (fullscreen) {

        fullscreen.onclick =
            async function () {

                if (!document.fullscreenElement) {

                    await document
                        .documentElement
                        .requestFullscreen();

                } else {

                    await document
                        .exitFullscreen();
                }
            };
    }


    // En esta versión robusta:
    // recarga total cada 5 segundos.
    // Así siempre toma los pedidos desde Odoo.
    setTimeout(
        function () {
            window.location.reload();
        },
        5000
    );

});
